import re
from pathlib import Path

ШЛЯХ = Path("дані") / "заголовки.txt"


def зробити_slug(рядок):
    # Кожна послідовність символів, що не є латинською літерою чи цифрою, стає одним дефісом.
    # Перевірка лише по ASCII, щоб не зачепити символи, які після lower() стали б латинськими.
    slug = re.sub(r"[^A-Za-z0-9]+", "-", рядок).strip("-")
    return slug.lower()


def main():
    with ШЛЯХ.open(encoding="utf-8") as f:
        for рядок in f:
            рядок = рядок.rstrip("\r\n")
            if рядок == "":
                continue
            print(зробити_slug(рядок))


if __name__ == "__main__":
    main()
